<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\RelyingParty\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Create\RelyingPartyCreateAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Update\RelyingPartyUpdateAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\List\RelyingPartyListAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Retrieve\RelyingPartyRetrieveAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Delete\RelyingPartyDeleteAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Enable\RelyingPartyEnableAllowDecision;
use Civi\Lughauth\Features\Access\RelyingParty\Application\Usecase\Disable\RelyingPartyDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlyForRootAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(RelyingPartyCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyCreateAllowDecision', $proposal);
    }
    public function checkUpdate(RelyingPartyUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyUpdateAllowDecision', $proposal);
    }
    public function checkList(RelyingPartyListAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyListAllowDecision', $proposal);
    }
    public function checkRetrieve(RelyingPartyRetrieveAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyRetrieveAllowDecision', $proposal);
    }
    public function checkDelete(RelyingPartyDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyDeleteAllowDecision', $proposal);
    }
    public function checkEnable(RelyingPartyEnableAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyEnableAllowDecision', $proposal);
    }
    public function checkDisable(RelyingPartyDisableAllowDecision $proposal): AllowDecision
    {
        return $this->check('RelyingPartyDisableAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on OnlyForRootAllow Relying party");
        $span = $this->startSpan("Check " . $name . " on OnlyForRootAllow Relying party");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!(($identity->hasScope("platform:global_access") && $identity->hasRole("admin")))) {
                    $proposal->deny('Disabled if not OnlyForRoot');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
